"use client";

import { useMemo, useState } from "react";
import { hongmenRoles, hongmenScenes } from "@/data/hongmen-banquet";
import { cn } from "@/lib/cn";
import { Panel } from "@/components/ui/panel";
import { PlaceholderArt } from "@/components/ui/placeholder-art";
import type { HongmenChoice } from "@/types/content";

export function HongmenDemo() {
  const initialRoleId = hongmenRoles[0]?.id ?? "";
  const [selectedRoleId, setSelectedRoleId] = useState(initialRoleId);
  const [progress, setProgress] = useState(1);
  const [choices, setChoices] = useState<Record<string, HongmenChoice>>({});

  const selectedRole =
    hongmenRoles.find((role) => role.id === selectedRoleId) ?? hongmenRoles[0];

  const visibleScenes = useMemo(
    () => hongmenScenes.slice(0, progress),
    [progress],
  );

  const currentScene = hongmenScenes[Math.min(progress - 1, hongmenScenes.length - 1)];
  const isFinished = progress >= hongmenScenes.length;

  const resetDemo = (roleId = selectedRoleId) => {
    setSelectedRoleId(roleId);
    setProgress(1);
    setChoices({});
  };

  const handleChoice = (sceneId: string, choice: HongmenChoice) => {
    setChoices((current) => ({
      ...current,
      [sceneId]: choice,
    }));
    setProgress((current) => Math.min(current + 1, hongmenScenes.length));
  };

  return (
    <div className="grid gap-6 xl:grid-cols-[0.95fr_1.35fr]">
      <div className="space-y-6">
        <Panel className="p-6">
          <div className="space-y-4">
            <div>
              <p className="text-xs uppercase tracking-[0.3em] text-amber-200/70">
                第一步
              </p>
              <h2 className="mt-3 font-display text-3xl text-stone-50">
                选择你的视角
              </h2>
              <p className="mt-3 text-sm leading-7 text-stone-300">
                这一阶段先固定为鸿门宴试玩。你可以先挑选扮演角色，再进入同一场历史事件的不同观察角度。
              </p>
            </div>

            <div className="space-y-4">
              {hongmenRoles.map((role) => {
                const active = role.id === selectedRoleId;

                return (
                  <button
                    key={role.id}
                    type="button"
                    onClick={() => resetDemo(role.id)}
                    className="w-full text-left"
                  >
                    <Panel
                      className={cn(
                        "p-4 transition-colors",
                        active
                          ? "border-amber-200/25 bg-amber-100/8"
                          : "hover:border-white/20",
                      )}
                    >
                      <div className="flex items-start gap-4">
                        <PlaceholderArt
                          label={role.portraitLabel}
                          tone={role.portraitTone}
                          className="w-28 shrink-0"
                        />
                        <div className="space-y-2">
                          <div className="flex items-center gap-3">
                            <h3 className="font-display text-2xl text-stone-50">
                              {role.name}
                            </h3>
                            <span className="rounded-full border border-white/10 px-3 py-1 text-xs text-stone-300">
                              {role.title}
                            </span>
                          </div>
                          <p className="text-sm leading-7 text-stone-300">
                            {role.summary}
                          </p>
                        </div>
                      </div>
                    </Panel>
                  </button>
                );
              })}
            </div>
          </div>
        </Panel>

        {selectedRole ? (
          <Panel className="p-6">
            <div className="space-y-4">
              <p className="text-sm text-stone-400">当前扮演</p>
              <h3 className="font-display text-3xl text-stone-50">
                {selectedRole.name}
              </h3>
              <p className="text-sm leading-7 text-stone-300">
                {selectedRole.perspective}
              </p>
              <div className="rounded-[24px] border border-white/10 bg-black/15 p-4 text-sm leading-7 text-stone-300">
                {selectedRole.pressure}
              </div>
            </div>
          </Panel>
        ) : null}
      </div>

      <div className="space-y-6">
        <Panel className="p-6">
          <div className="grid gap-5 lg:grid-cols-[1.15fr_0.85fr]">
            <div className="space-y-4">
              <p className="text-xs uppercase tracking-[0.3em] text-amber-200/70">
                第二步
              </p>
              <h2 className="font-display text-3xl text-stone-50">
                进入鸿门宴现场
              </h2>
              <p className="text-sm leading-7 text-stone-300">
                当前用假数据搭建对话区、背景区和关键抉择按钮。后续只需要替换素材和补充分支，就能继续往下扩。
              </p>
            </div>
            <PlaceholderArt
              label="宴"
              caption="背景占位图：营帐、火光、酒器与兵甲的压迫感"
              tone="crimson"
              className="min-h-[240px]"
            />
          </div>
        </Panel>

        <Panel className="p-6">
          <div className="space-y-4">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div>
                <p className="text-sm text-stone-400">试玩剧情区</p>
                <p className="mt-2 text-lg text-stone-100">
                  你正在以 {selectedRole?.name ?? "未选择角色"} 的视角体验鸿门宴
                </p>
              </div>
              <button
                type="button"
                onClick={() => resetDemo(selectedRoleId)}
                className="rounded-full border border-white/10 px-4 py-2 text-sm text-stone-300 transition hover:text-stone-50"
              >
                重新开始试玩
              </button>
            </div>

            <div className="space-y-4">
              {visibleScenes.map((scene, index) => {
                const chosen = choices[scene.id];
                const isDecision = scene.type === "decision";

                return (
                  <div
                    key={scene.id}
                    className="rounded-[24px] border border-white/10 bg-black/15 p-5"
                  >
                    <div className="flex items-start gap-4">
                      <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl border border-white/10 bg-white/5 font-display text-lg text-stone-50">
                        {scene.speaker.slice(0, 1)}
                      </div>
                      <div className="space-y-2">
                        <div className="flex flex-wrap items-center gap-3">
                          <p className="font-medium text-stone-100">
                            {index + 1}. {scene.speaker}
                          </p>
                          <span className="text-xs uppercase tracking-[0.25em] text-stone-500">
                            {scene.type}
                          </span>
                        </div>
                        <p className="text-sm leading-7 text-stone-300">
                          {scene.text}
                        </p>
                        {scene.note ? (
                          <p className="text-xs leading-6 text-stone-500">
                            {scene.note}
                          </p>
                        ) : null}
                        {isDecision && chosen ? (
                          <div className="mt-3 rounded-[20px] border border-amber-200/20 bg-amber-100/10 p-4 text-sm leading-7 text-amber-50">
                            <p className="font-medium">{chosen.label}</p>
                            <p className="mt-2 text-amber-50/85">{chosen.outcome}</p>
                          </div>
                        ) : null}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {currentScene?.type === "decision" && !choices[currentScene.id] ? (
              <div className="space-y-3 rounded-[24px] border border-amber-200/20 bg-amber-100/8 p-5">
                <p className="text-sm text-amber-50/80">请选择你的行动</p>
                {currentScene.choices?.map((choice) => (
                  <button
                    key={choice.id}
                    type="button"
                    onClick={() => handleChoice(currentScene.id, choice)}
                    className="flex w-full items-center justify-between gap-3 rounded-[18px] border border-white/10 bg-black/20 px-4 py-3 text-left text-sm text-stone-200 transition hover:border-amber-200/30 hover:text-stone-50"
                  >
                    <span>{choice.label}</span>
                    {choice.isHistorical ? (
                      <span className="rounded-full border border-amber-200/30 px-3 py-1 text-xs text-amber-50">
                        历史走向
                      </span>
                    ) : null}
                  </button>
                ))}
              </div>
            ) : null}

            {!isFinished && currentScene?.type !== "decision" ? (
              <button
                type="button"
                onClick={() =>
                  setProgress((current) => Math.min(current + 1, hongmenScenes.length))
                }
                className="rounded-full border border-amber-200/25 bg-amber-100/10 px-5 py-3 text-sm text-amber-50 transition hover:border-amber-200/40 hover:bg-amber-100/15"
              >
                继续推进剧情
              </button>
            ) : null}

            {isFinished ? (
              <div className="rounded-[24px] border border-emerald-200/20 bg-emerald-100/8 p-5 text-sm leading-7 text-stone-200">
                这一轮试玩已经走完。当前版本已经具备角色选择、对话推进、关键决策和重开能力，下一阶段可以继续接更长剧情和真实素材。
              </div>
            ) : null}
          </div>
        </Panel>
      </div>
    </div>
  );
}
